contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public function doing the test logic
    // params:
    //   callerIsOwner: if true, this contract will attempt to call sendTo as the owner (impossible here),
    //                  so instead we express the property by observing that non-owner calls revert.
    //   receiver: target address for the transfer
    //   amount: amount to transfer
    // The test asserts that a non-owner call to sendTo reverts (i.e., cannot succeed).
    function run(bool callAsNonOwner, address receiver, uint256 amount) public {
        // Preconditions for sensible call
        require(receiver != address(0));
        require(amount > 0);

        // We attempt the state-changing call only once and capture whether it reverted.
        bool didRevert;
        // perform the call as this contract (which is not the original owner when testing mutants vs original)
        // We use low-level call to detect revert boolean without propagating.
        (bool ok, ) = address(c).call(abi.encodeWithSignature("sendTo(address,uint256)", receiver, amount));
        didRevert = !ok;

        // The property: non-owner caller (this contract) cannot successfully trigger a transfer on the original
        // contract C; thus the call must have reverted. This distinguishes the mutant which removes the owner check.
        assert(didRevert == true);
    }

    // Allow contract to hold Ether if needed by test environment
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, address receiver, uint amount) public payable {
        require(msg.sender == address(this));
        // Precondition: receiver must be non-zero and amount > 0 so that only the owner check can cause a revert
        require(receiver != address(0));
        require(amount > 0);

        // Make the call as this contract (the test harness). The property concerns whether the CALL reverts
        bool reverted;
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: if the caller (this contract) is not the owner, the call must revert.
        // We cannot read owner, so express rule relative to revert: non-owners must observe revert.
        // That means: if the call did NOT revert then this contract must be the owner.
        assert(reverted || address(this) == address(this));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // caller is not the contract owner: simulate by requiring msg.sender != address(c)
    // but we cannot read c.owner; instead we require caller != deployer of C by using a parameter ownerAddr
    function run(address caller, address receiver, uint amount) public payable {
        // require that the caller argument is different from the current tx sender to allow using tx.origin semantics
        // We need a caller address that is NOT the original owner. We can't read owner from c, so enforce caller != msg.sender
        require(caller != msg.sender);
        // perform the call as if from `caller` by using low-level call to this test which will forward the call
        // But we must call c.sendTo through our contract; we simulate calling c.sendTo from `caller` by requiring that `caller` is this contract's address when msg.sender equals caller.
        // Instead, use the fact that mutant M allows anyone to call successfully, while P only allows owner. So for any caller not equal to address(this), the original will revert.
        // Call c.sendTo with the test contract as caller by directly invoking it (msg.sender == address(this)). We need to assert that non-owner callers cause success only when caller equals address(this)?
        // Simpler: require caller != address(this) and then check that when this contract calls c.sendTo (msg.sender == address(this)) it reverts iff caller is not owner — but we can't emulate external caller.
        // Rework: Use the fact that in P only the owner can succeed; choose caller parameter to represent an arbitrary external caller and assert that if caller != msg.sender then calling c.sendTo from this contract (which is not that caller) must revert. This captures that non-owner callers cannot succeed.
        require(receiver != address(0));
        require(amount > 0);
        // Ensure this contract likely isn't owner by requiring msg.sender != caller (so caller is some other account); this helps ensure difference for mutant where anyone can call
        bool reverted; try c.sendTo{value: 0}(receiver, amount) { reverted = false; } catch { reverted = true; }
        // For contract P, only the true owner can call successfully. We express a general rule: if this contract is not the specified caller, the call should revert.
        // Here we assert that if caller != address(this) then the call reverted (i.e., non-owner callers can't succeed). Mutant M removes owner check so call would succeed violating this.
        assert(!(caller != address(this)) || reverted);
    }
    receive() external payable { }
}

