pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: caller and amount
    function testFuzz_property(address caller, uint256 amount) public {
        // admissible domain: receiver must be non-zero (we will use caller as receiver), amount > 0 and not absurdly large
        vm.assume(caller != address(0));
        uint256 capped = bound(amount, 1, 1 ether);

        // Fund the contract with some Ether so sendTo can transfer out
        vm.deal(address(c), 1 ether);

        // If caller is the owner (deployer in setUp), then call should be allowed by reference contract.
        // If caller is not the owner, reference must prevent transfer and contract balance must remain 1 ether.
        // The mutant that removed the owner check will allow non-owner callers to transfer out and reduce balance for some inputs.

        // perform call as caller, sending no value (sendTo transfers from contract balance)
        bool ok;
        vm.prank(caller);
        try c.sendTo(caller, capped) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: if caller is not the owner, the reference contract should not have allowed a successful send (so contract balance stays 1 ether)
        // We observe this by checking: either call reverted (ok == false) OR (if call succeeded) caller must be the owner.
        // This expresses the invariant: only owner can successfully invoke sendTo.
        address owner = address(this); // placeholder; cannot read owner (it's internal), so derive owner: the deployer is the test contract (setUp used new C() from this contract)
        // The deployer (owner) is address(this) as setUp executed new C() from this contract

        // assert: if ok then caller == owner, equivalently: !(ok && caller != owner)
        assertTrue(!(ok && caller != owner));
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // This test drives c.sendTo and asserts that it reverts on failure-to-transfer.
    // Inputs:
    // - receiver: address to send to
    // - amount: amount to send (in wei)
    // Precondition: this contract must hold at least `amount` wei so the transfer attempt is meaningful.
    function run(address payable receiver, uint256 amount) public {
        require(address(this).balance >= amount, "insufficient balance for test");
        // call the target function; it will revert on failure with P (transfer)
        // but in M it may return false from .send and then our assert should detect non-reversion.
        bool reverted = false;
        // perform the call and detect if it reverts
        (bool ok, ) = address(c).call(abi.encodeWithSignature("sendTo(address,uint256)", receiver, amount));
        reverted = !ok;

        // General rule: the sendTo call must revert (i.e., transfers that fail cause revert).
        // This holds for original P (uses transfer which reverts on failure) but is violated by M (uses send and then tries require(ok) - however if send returns false and require(ok) is present it will still revert; to distinguish we rely on receivers that consume gas and cause send to return false WITHOUT triggering low-level issues. The intended distinguishing is that original transfer triggers automatic revert on failure and thus the external call result is always revert when transfer fails.
        assert(reverted == true);
    }

    // Allow this contract to receive ETH for funding tests
    receive() external payable {}
}

