pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters: amount to send and a boolean deciding whether receiver will revert
    function testFuzz_property(uint256 amount, bool makeRevert) public {
        // keep amount in a reasonable wide range but >0
        vm.assume(amount > 0);
        amount = bound(amount, 1, 1 ether);

        // deploy either a normal receiver or a reverting receiver based on fuzzed boolean
        address receiver;
        if (makeRevert) {
            Reverter r = new Reverter();
            receiver = address(r);
        } else {
            SimpleReceiver s = new SimpleReceiver();
            receiver = address(s);
        }

        // fund the contract c so it can send
        vm.deal(address(this), amount);
        // send funds into c from this test contract
        (bool sent,) = address(c).call{value: amount}(abi.encodeWithSignature("sendTo(address,uint256)", receiver, uint256(0)));
        // Above call attempts sendTo with amount 0 and will revert due to amount>0 requirement; instead fund via self-destruct helper
        // Use a funding helper to forward ETH to c
        FundHelper fh = new FundHelper{value: amount}();
        fh.fund(address(c));

        // record contract balance before
        uint256 before = address(c).balance;
        // ensure caller is owner (deployer of c in setUp is this contract? No: c was deployed in setUp via new C(), msg.sender there was this test contract)
        // So this contract (address(this)) is owner. Call sendTo as owner and send amount
        vm.prank(address(this));
        bool ok;
        try c.sendTo(receiver, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 after = address(c).balance;

        // General property: For the correct contract using transfer, when the owner calls sendTo with a funded amount
        // to a non-zero receiver, the contract's balance decreases by exactly amount (i.e., after == before - amount).
        // The mutant using .send can fail when the receiver's fallback reverts and thus not decrease balance; so
        // we assert the property on c's observable balance change.
        assertTrue(after + amount == before);
    }
}

// Helper to create a contract that always reverts on receiving ETH
contract Reverter {
    fallback() external payable { revert("nope"); }
    receive() external payable { revert("nope"); }
}

// Simple receiver that accepts ETH
contract SimpleReceiver {
    receive() external payable {}
}

// Helper to fund target via constructor then selfdestruct to send ETH
contract FundHelper {
    constructor() payable {}
    function fund(address target) external {
        selfdestruct(payable(target));
    }
}
